func toJSONValue(_ json: Any) -> JSONValue {
    switch json {
    case let dict as [String: Any]:
        return .object(Dictionary(uniqueKeysWithValues: dict.map { (key, value) in (key, toJSONValue(value)) }))
    case let arr as [Any]:
        return .array(arr.map { toJSONValue($0) })
    case let str as String:
        return .string(str)
