    ensure_dept_capacity();
    for (int i = 0; i < num_depts; i++) {
        if (strcmp(depts[i].name, name) == 0) {
            depts[i].total_salary += salary;
            depts[i].count++;
            return;
        }
    }
    strncpy(depts[num_depts].name, name, 255);
