static void skip_whitespace(const char **p) {
    while (**p == ' ' || **p == '\t' || **p == '\n' || **p == '\r') (*p)++;
}

static int parse_string(const char **p, char *out, int maxlen) {
    if (**p != '"') return 0;
    (*p)++;
    int i = 0;
    while (**p && **p != '"' && i < maxlen - 1) {
        if (**p == '\\') {
            (*p)++;
            switch (**p) {
                case '"': out[i++] = '"'; break;
                case '\\': out[i++] = '\\'; break;
                case '/': out[i++] = '/'; break;
                case 'n': out[i++] = '\n'; break;
                case 't': out[i++] = '\t'; break;
                case 'r': out[i++] = '\r'; break;
                case 'b': out[i++] = '\b'; break;
                case 'f': out[i++] = '\f'; break;
                default: out[i++] = **p; break;
            }
        } else {
            out[i++] = **p;
        }
        (*p)++;
    }
    out[i] = '\0';
    if (**p == '"') (*p)++;
    return 1;
}

static int parse_number(const char **p, double *out) {
    skip_whitespace(p);
    char numstr[64];
    int i = 0;
    if (**p == '-') numstr[i++] = *((*p)++);
    while (**p && (**p >= '0' && **p <= '9')) numstr[i++] = *((*p)++);
    if (**p == '.') {
        numstr[i++] = *((*p)++);
        while (**p && (**p >= '0' && **p <= '9')) numstr[i++] = *((*p)++);
    }
    if (**p == 'e' || **p == 'E') {
        numstr[i++] = *((*p)++);
        if (**p == '+' || **p == '-') numstr[i++] = *((*p)++);
        while (**p && (**p >= '0' && **p <= '9')) numstr[i++] = *((*p)++);
    }
    numstr[i] = '\0';
    *out = atof(numstr);
    return 1;
}

