const edges: { from: string; to: string; weight: number }[] = data.edges;

// Build adjacency list
const adj: Map<string, Map<string, number>> = new Map();
for (const node of nodes) {
    adj.set(node, new Map());
}
for (const edge of edges) {
    adj.get(edge.from)!.set(edge.to, edge.weight);
    adj.get(edge.to)!.set(edge.from, edge.weight);
}

// Dijkstra's algorithm
const dist: Map<string, number> = new Map();
const visited: Set<string> = new Set();

for (const node of nodes) {
    dist.set(node, Infinity);
}
dist.set("A", 0);

const heap: [number, string][] = [[0, "A"]];

while (heap.length > 0) {
    let minIdx = 0;
    for (let i = 1; i < heap.length; i++) {
        if (heap[i][0] < heap[minIdx][0]) {
            minIdx = i;
        }
    }
    const [d, u] = heap.splice(minIdx, 1)[0];

    if (visited.has(u)) continue;
    visited.add(u);

    for (const [v, w] of adj.get(u)!) {
        const newDist = d + w;
        if (newDist < dist.get(v)!) {
            dist.set(v, newDist);
            heap.push([newDist, v]);
        }
    }
}

