interface FileInfo {
  relativePath: string;
  lines: number;
  chars: number;
}

interface ExtensionGroup {
  extension: string;
  files: FileInfo[];
  totalLines: number;
  totalChars: number;
}

function getExtension(filePath: string): string {
  const ext = path.extname(filePath);
  return ext || '';
}

function countLinesAndChars(filePath: string): { lines: number; chars: number } {
  const content = fs.readFileSync(filePath);
  const chars = content.length;
  const text = content.toString();
  const newlineCount = (text.match(/\n/g) || []).length;
  const lines = text.length === 0 ? 0 : newlineCount + (text.endsWith('\n') ? 0 : 1);
  return { lines, chars };
}

function walkDir(dir: string, relativePath: string): FileInfo[] {
  const files: FileInfo[] = [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    if (entry.isSymbolicLink()) continue;

    const fullPath = path.join(dir, entry.name);
    const relPath = relativePath ? path.join(relativePath, entry.name) : entry.name;

    if (entry.isDirectory()) {
      files.push(...walkDir(fullPath, relPath));
    } else if (entry.isFile()) {
      const { lines, chars } = countLinesAndChars(fullPath);
      files.push({ relativePath: relPath.replace(/\\/g, '/'), lines, chars });
    }
  }

  return files;
}

