static char *run_cmd(const char *cmd) {
    FILE *fp = popen(cmd, "r");
    if (!fp) return NULL;
    char buf[256];
    size_t cap = 256, len = 0;
    char *out = malloc(cap);
    if (!out) { pclose(fp); return NULL; }
    out[0] = '\0';
    while (fgets(buf, sizeof(buf), fp)) {
        size_t blen = strlen(buf);
        if (len + blen + 1 >= cap) {
            cap *= 2;
            char *tmp = realloc(out, cap);
            if (!tmp) { free(out); pclose(fp); return NULL; }
            out = tmp;
        }
        strcpy(out + len, buf);
        len += blen;
    }
    pclose(fp);
    while (len > 0 && (out[len-1] == '\n' || out[len-1] == '\r' || out[len-1] == ' ' || out[len-1] == '\t')) {
        out[--len] = '\0';
    }
    return out;
}

static void json_escape(const char *s, FILE *out) {
    while (*s) {
        switch (*s) {
            case '"':  fputs("\\\"", out); break;
            case '\\': fputs("\\\\", out); break;
            case '\n': fputs("\\n", out); break;
            case '\r': fputs("\\r", out); break;
            case '\t': fputs("\\t", out); break;
            default:   fputc(*s, out);
        }
        s++;
    }
}

