      const row: number[] = [];
      for (let k = 0; k < n; k++) {
        if (k !== j) row.push(m[i][k]);
      }
      subMatrix.push(row);
    }
    det += (j % 2 === 0 ? 1 : -1) * m[0][j] * determinant(subMatrix);
  }
  return det;
}

function formatMatrix(matrix: number[][]): string {
  return matrix.map(row => {
    return "  " + row.map(v => String(v).padStart(4, " ")).join(" ");
  }).join("\n");
}

