// Matrix multiplication function
func multiply(_ A: [[Int]], _ B: [[Int]]) -> [[Int]] {
    let rowsA = A.count
    let colsA = A[0].count
    let colsB = B[0].count

    var C = [[Int]](repeating: [Int](repeating: 0, count: colsB), count: rowsA)

    for i in 0..<rowsA {
        for j in 0..<colsB {
            var sum = 0
            for k in 0..<colsA {
                sum += A[i][k] * B[k][j]
            }
            C[i][j] = sum
        }
    }
    return C
}

// Determinant function for 3x3 matrix
func determinant(_ M: [[Int]]) -> Int {
    let a = M[0][0]
    let b = M[0][1]
    let c = M[0][2]
    let d = M[1][0]
    let e = M[1][1]
    let f = M[1][2]
    let g = M[2][0]
    let h = M[2][1]
    let i = M[2][2]

    return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)
}

